441	    #[test]
442	    fn init_command_creation() {
443	        let temp = TempDir::new().unwrap();
444	        let args = InitArgs::default();
445	        let cmd = InitCommand::new(temp.path(), args);
446	
447	        assert_eq!(cmd.project_root(), temp.path());
448	        assert!(!cmd.config_exists());
449	    }
