451	    #[test]
452	    fn create_config_basic() {
453	        let temp = TempDir::new().unwrap();
454	        let args = InitArgs::default();
455	        let cmd = InitCommand::new(temp.path(), args);
456	
457	        let steps: Vec<(&str, Option<&Template>)> =
458	            vec![("bundle-install", None), ("yarn-install", None)];
459	        let config = cmd.create_config(&steps, None);
460	
461	        assert!(config.contains("bundle-install"));
462	        assert!(config.contains("yarn-install"));
463	        assert!(config.contains("template: bundle-install"));
464	        assert!(config.contains("template: yarn-install"));
465	        assert!(config.contains("workflows:"));
466	        assert!(config.contains("default:"));
467	        assert!(config.contains("steps: [bundle-install, yarn-install]"));
468	    }
