470	    #[test]
471	    fn create_config_with_templates() {
472	        let temp = TempDir::new().unwrap();
473	        let args = InitArgs::default();
474	        let cmd = InitCommand::new(temp.path(), args);
475	
476	        let loader = BuiltinLoader::new().unwrap();
477	        let bundler = loader.get("bundle-install");
478	        let yarn = loader.get("yarn-install");
479	
480	        let steps: Vec<(&str, Option<&Template>)> =
481	            vec![("bundle-install", bundler), ("yarn-install", yarn)];
482	        let config = cmd.create_config(&steps, None);
483	
484	        // Should contain template references
485	        assert!(config.contains("template: bundle-install"));
486	        assert!(config.contains("template: yarn-install"));
487	
488	        // Should contain commented-out command info from templates
489	        assert!(config.contains("# command: bundle install"));
490	        assert!(config.contains("# command: yarn install"));
491	
492	        // Should contain customization guide in the header
493	        assert!(config.contains("# Override any template field per-step:"));
494	    }
