509	    #[test]
510	    fn create_config_includes_schema_line_when_path_provided() {
511	        let temp = TempDir::new().unwrap();
512	        let args = InitArgs::default();
513	        let cmd = InitCommand::new(temp.path(), args);
514	
515	        let schema = PathBuf::from("/home/alice/.bivvy/schema.json");
516	        let steps: Vec<(&str, Option<&Template>)> = vec![("bundle-install", None)];
517	        let config = cmd.create_config(&steps, Some(&schema));
