109	/// Check if options form a yes/no pair.
110	fn is_yes_no(options: &[PromptOption]) -> bool {
111	    options.len() == 2
112	        && options.iter().any(|o| o.value == "yes")
113	        && options.iter().any(|o| o.value == "no")
114	}
