147	impl Prompter for TerminalUI {
148	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
149	        // Re-claim foreground process group: child commands may have
150	        // stolen it on exit, leaving us unable to read input.
151	        #[cfg(unix)]
152	        claim_foreground();
153	
154	        if let Some(surface) = &self.surface {
155	            surface.with_cursor_freed(|| prompt_user(prompt, &self.term))
156	        } else {
157	            prompt_user(prompt, &self.term)
158	        }
159	    }
160	}
161	
162	impl SpinnerFactory for TerminalUI {
163	    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
164	        if self.mode.shows_spinners() {
165	            // Outside a run path: ad-hoc spinner with no surface
166	            // coordination. Used by init/status/etc. for one-off
167	            // operations.
168	            Box::new(ProgressSpinner::new(message))
169	        } else {
170	            Box::new(ProgressSpinner::hidden())
171	        }
172	    }
173	
174	    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
175	        if self.mode.shows_spinners() {
176	            Box::new(ProgressSpinner::with_indent(message, indent))
177	        } else {
178	            Box::new(ProgressSpinner::hidden())
179	        }
180	    }
181	}
182	
183	impl ProgressDisplay for TerminalUI {
184	    fn show_header(&mut self, title: &str) {
185	        if self.mode.shows_status() {
186	            self.println(&format!("\n{}\n", self.theme.format_header(title)));
187	        }
188	    }
189	
190	    fn show_progress(&mut self, current: usize, total: usize) {
191	        if self.mode.shows_status() {
192	            self.println(
193	                &self
194	                    .theme
195	                    .dim
196	                    .apply_to(format!("[{}/{}]", current, total))
197	                    .to_string(),
198	            );
199	        }
200	    }
201	}
