                if let Some(completion) = &self.completion {
                    let input: String = chars.clone().into_iter().collect();
                    if let Some(x) = completion.get(&input) {
                        term.clear_chars(chars.len())?;
                        chars.clear();
                        position = 0;
                        for ch in x.chars() {
                            chars.insert(position, ch);
