267	/// Execute a fix command with the step's environment and working directory.
268	///
269	/// Output is streamed through `execute_streaming` with each line prefixed
270	/// by `"    fix: "` for consistent TUI formatting. After the command
271	/// completes, any buffered terminal input is drained to prevent queued
272	/// keypresses from triggering unintended recovery menu actions.
273	pub fn run_fix(command: &str, project_root: &Path, env: &HashMap<String, String>) -> Result<bool> {
274	    let options = CommandOptions {
275	        cwd: Some(project_root.to_path_buf()),
276	        env: env.clone(),
277	        ..Default::default()
278	    };
279	
280	    let callback: OutputCallback = Box::new(FixOutputSink);
281	
282	    let result = execute_streaming(command, &options, callback)?;
283	
284	    // Drain buffered terminal input to prevent queued keypresses
285	    // from triggering unintended recovery menu actions.
286	    #[cfg(unix)]
287	    crate::shell::command::drain_input();
288	
289	    Ok(result.success)
290	}
