90	/// Manages the execution of a single step within a workflow.
91	///
92	/// Handles step-level concerns: printing step headers, evaluating checks,
93	/// showing prompts, executing the step command, and handling recovery.
94	/// Does NOT know about workflow state, progress bars, or summaries.
95	pub(super) struct StepManager<'a> {
96	    step: &'a ResolvedStep,
97	    step_name: &'a str,
98	    index: usize,
99	    total: usize,
100	    theme: &'a BivvyTheme,
101	}
102	
103	impl<'a> StepManager<'a> {
104	    /// Create a new StepManager for a specific step.
105	    pub fn new(
106	        step: &'a ResolvedStep,
107	        step_name: &'a str,
108	        index: usize,
109	        total: usize,
110	        theme: &'a BivvyTheme,
111	    ) -> Self {
112	        Self {
113	            step,
114	            step_name,
115	            index,
116	            total,
117	            theme,
118	        }
119	    }
120	
121	    /// Format the step number string, e.g., `[1/7]`.
122	    fn step_number(&self) -> String {
123	        format!("[{}/{}]", self.index + 1, self.total)
124	    }
125	
126	    /// Compute the indentation width that aligns content under the step name.
127	    fn step_indent(&self) -> usize {
128	        self.step_number().len() + 1 // +1 for the space after
129	    }
130	
131	    /// Compute the indentation padding string.
132	    fn step_pad(&self) -> String {
133	        " ".repeat(self.step_indent())
134	    }
135	
136	    /// Format the step display line with optional title.
137	    fn step_header_text(&self) -> String {
138	        let step_number = self.step_number();
139	        let step_header = format!(
140	            "{} {}",
141	            self.theme.step_number.apply_to(&step_number),
142	            self.theme.step_title.apply_to(self.step_name)
143	        );
144	        if self.step_name == self.step.title {
145	            step_header
146	        } else {
147	            format!(
148	                "{} {} {}",
149	                step_header,
150	                self.theme.dim.apply_to("—"),
151	                self.theme.dim.apply_to(&self.step.title)
152	            )
153	        }
154	    }
155	
156	    /// Execute the step through the full decision/execution lifecycle.
157	    ///
158	    /// This method handles:
159	    /// - Requirement gap resolution
160	    /// - Decision engine evaluation
161	    /// - Prompts (rerun, autorun, confirm, sensitive)
162	    /// - Step-level template prompts
163	    /// - Step execution with retry and recovery
164	    /// - Event emission for all step-level events
165	    ///
166	    /// Returns a `StepAction` describing what happened.
167	    #[allow(clippy::too_many_arguments)]
168	    pub fn execute(
169	        &self,
170	        opts: &StepExecutionOptions<'_>,
171	        context: &mut InterpolationContext,
172	        step_overrides: &HashMap<String, StepOverride>,
173	        gap_checker: &mut Option<&mut GapChecker<'_>>,
174	        snapshot_store: &mut SnapshotStore,
175	        steps: &HashMap<String, ResolvedStep>,
176	        state: Option<&StateStore>,
177	        satisfaction_cache: &mut SatisfactionCache,
178	        failed_steps: &HashSet<String>,
179	        user_skipped_steps: &HashSet<String>,
180	        satisfied_steps: &HashSet<String>,
181	        named_check_results: &mut HashMap<String, CheckResult>,
182	        results: &[StepResult],
183	        ui: &mut dyn UserInterface,
184	        step_display: &mut dyn StepDisplay,
185	        event_bus: &mut EventBus,
186	    ) -> Result<StepAction> {
187	        let step_pad = self.step_pad();
188	        let step_header = self.step_header_text();
189	
190	        // Emit step planned
191	        event_bus.emit(&BivvyEvent::StepPlanned {
192	            name: self.step_name.to_string(),
193	            index: self.index,
194	            total: self.total,
195	        });
196	
197	        // Blank line between steps
198	        if self.index > 0 {
199	            ui.message("");
200	        }
201	
202	        // ── Pre-engine: requirement gap resolution ──
203	        let mut unresolved_gaps: HashSet<String> = HashSet::new();
204	        if let Some(ref mut checker) = gap_checker {
205	            let provided = if opts.provided_requirements.is_empty() {
206	                None
207	            } else {
208	                Some(opts.provided_requirements)
209	            };
210	            let gaps = checker.check_step(self.step, provided);
211	            if !gaps.is_empty() {
212	                let installer_ctx = installer::default_context();
213	                let resolved =
214	                    installer::handle_gaps(&gaps, checker, ui, opts.interactive, &installer_ctx);
215	                match resolved {
216	                    Ok(true) => {}
217	                    Ok(false) | Err(_) => {
218	                        for gap in &gaps {
219	                            event_bus.emit(&BivvyEvent::RequirementGap {
220	                                name: self.step_name.to_string(),
221	                                requirement: gap.requirement.clone(),
222	                                status: format!("{:?}", gap.status),
223	                            });
224	                        }
225	                        unresolved_gaps.insert(self.step_name.to_string());
226	                    }
227	                }
228	            }
229	        }
230	
231	        let needs_force = opts.should_force(self.step_name) || self.step.behavior.force;
232	
233	        // ── Pre-engine: collect named check results for cross-step refs ──
234	        if !opts.dry_run {
235	            if let Some(check) = self.step.execution.effective_check() {
236	                if check.has_named_checks() {
237	                    let mut evaluator =
238	                        CheckEvaluator::new(opts.project_root, context, snapshot_store);
239	                    let step_named = satisfaction::collect_named_check_results(
240	                        self.step_name,
241	                        &check,
242	                        &mut evaluator,
243	                    );
244	                    named_check_results.extend(step_named);
245	                }
246	            }
247	        }
248	
249	        // ── Decision Engine ──
250	        let eval_result = if opts.dry_run {
251	            EvaluationResult {
252	                decision: StepDecision::AutoRun,
253	                reason: "dry run".to_string(),
254	                satisfaction: None,
255	            }
256	        } else {
257	            let mut engine_ctx = EngineContext {
258	                steps,
259	                project_root: opts.project_root,
260	                interpolation: context,
261	                snapshot_store,
262	                state,
263	                step_overrides,
264	                force: opts.force_steps,
265	                force_all: opts.force_all,
266	                named_check_results,
267	                satisfaction_cache,
268	                evaluated: HashMap::new(),
269	                failed_steps,
270	                user_skipped_steps,
271	                satisfied_steps,
272	                unresolved_gaps: &unresolved_gaps,
273	            };
274	            engine::evaluate_step(self.step_name, &mut engine_ctx)
275	        };
276	
277	        // Emit any baseline events from check evaluation
278	        emit_baseline_events(snapshot_store, event_bus);
279	
280	        // ── Act on the engine's decision ──
281	        match &eval_result.decision {
282	            StepDecision::Block { reason } => {
283	                return self.handle_block(
284	                    reason,
285	                    &step_header,
286	                    &step_pad,
287	                    failed_steps,
288	                    event_bus,
289	                    step_display,
290	                );
291	            }
292	
293	            StepDecision::Skip {
294	                reason: SkipReason::AutoSatisfied,
295	            } => {
296	                return self.handle_auto_satisfied(
297	                    &eval_result,
298	                    &step_header,
299	                    &step_pad,
300	                    needs_force,
301	                    event_bus,
302	                    step_display,
303	                );
304	            }
305	
306	            StepDecision::Prompt { prompt_key } => {
307	                step_display.message(&step_header);
308	
309	                if opts.interactive {
310	                    let outcome = self.handle_prompt(
311	                        prompt_key,
312	                        &eval_result,
313	                        &step_pad,
314	                        needs_force,
315	                        event_bus,
316	                        ui,
317	                        step_display,
318	                    )?;
319	                    if let Some(outcome) = outcome {
320	                        return Ok(outcome);
321	                    }
322	                    // None means fall through to execution
323	                }
324	                // Non-interactive: fall through to execution
325	            }
326	
327	            StepDecision::AutoRun | StepDecision::Run => {
328	                step_display.message(&step_header);
329	            }
330	
331	            StepDecision::Skip { reason } => {
332	                step_display.message(&step_header);
333	                step_display.message(&format!(
334	                    "{}{}",
335	                    step_pad,
336	                    StatusKind::Skipped.format(self.theme, reason.message())
337	                ));
338	                event_bus.emit(&BivvyEvent::StepSkipped {
339	                    name: self.step_name.to_string(),
340	                    reason: reason.message().to_string(),
341	                });
342	                event_bus.emit(&BivvyEvent::StepOutcome {
343	                    name: self.step_name.to_string(),
344	                    outcome: skip_reason_to_outcome(reason),
345	                    detail: Some(reason.message().to_string()),
346	                    duration_ms: None,
347	                });
348	                return Ok(StepAction::Skipped(
349	                    StepResult::skipped(&self.step.name, CheckResult::passed(reason.message())),
350	                    SkipCategory::Other,
351	                ));
352	            }
353	        }
354	
355	        // ── Step-level prompts (template inputs) ──
356	        if !self.step.output.prompts.is_empty() {
357	            for prompt_config in &self.step.output.prompts {
358	                if context.resolve(&prompt_config.key).is_some() {
359	                    continue;
360	                }
361	
362	                if !opts.interactive {
363	                    if let Some(default) = &prompt_config.default {
364	                        let default_str = match default {
365	                            serde_yaml::Value::String(s) => s.clone(),
366	                            serde_yaml::Value::Bool(b) => b.to_string(),
367	                            serde_yaml::Value::Number(n) => n.to_string(),
368	                            _ => format!("{:?}", default),
369	                        };
370	                        context
371	                            .prompts
372	                            .insert(prompt_config.key.clone(), default_str);
373	                    } else {
374	                        return Err(BivvyError::StepExecutionError {
375	                            step: self.step_name.to_string(),
376	                            message: format!(
377	                                "Prompt '{}' requires a value in non-interactive mode. \
378	                                 Set via env var, template input, or provide a default.",
379	                                prompt_config.key
380	                            ),
381	                        });
382	                    }
383	                    continue;
384	                }
385	
386	                let ui_prompt = config_prompt_to_ui_prompt(prompt_config);
387	                let result = ui.prompt(&ui_prompt)?;
388	                context
389	                    .prompts
390	                    .insert(prompt_config.key.clone(), result.as_string());
391	            }
392	        }
393	
394	        // ── Build step context and emit decision to run ──
395	        let step_ctx = StepContext {
396	            name: self.step_name,
397	            command: &self.step.execution.command,
398	            requires: &self.step.requires,
399	            template: None,
400	        };
401	
402	        event_bus.emit(&BivvyEvent::StepDecided {
403	            name: self.step_name.to_string(),
404	            decision: "run".to_string(),
405	            reason: None,
406	            trace: Some(DecisionTrace {
407	                behavior_flags: make_behavior_flags(self.step, needs_force),
408	                ..Default::default()
409	            }),
410	        });
411	        event_bus.emit(&BivvyEvent::StepStarting {
412	            name: self.step_name.to_string(),
413	        });
414	
415	        // ── Build workflow state for diagnostic funnel ──
416	        let workflow_state = {
417	            let step_refs: Vec<(&str, &ResolvedStep)> = steps
418	                .iter()
419	                .map(|(name, step)| (name.as_str(), step))
420	                .collect();
421	            let mut outcomes = HashMap::new();
422	            for r in results {
423	                outcomes.insert(r.name.clone(), r.status());
424	            }
425	            for s in satisfied_steps {
426	                outcomes.entry(s.clone()).or_insert(StepStatus::Completed);
427	            }
428	            for s in failed_steps {
429	                outcomes.entry(s.clone()).or_insert(StepStatus::Failed);
430	            }
431	            for s in user_skipped_steps {
432	                outcomes.entry(s.clone()).or_insert(StepStatus::Skipped);
433	            }
434	            (step_refs, outcomes)
435	        };
436	        let ws = diagnostic::WorkflowState {
437	            steps: &workflow_state.0,
438	            outcomes: &workflow_state.1,
439	        };
440	
441	        // ── Execute step with retry and recovery ──
442	        let step_number = self.step_number();
443	        let step_indent = self.step_indent();
444	        let exec_result = execute_step_with_recovery(
445	            self.step,
446	            self.step_name,
447	            &step_number,
448	            step_indent,
449	            opts.project_root,
450	            context,
451	            opts.base_env,
452	            opts.process_env,
453	            needs_force,
454	            opts.dry_run,
455	            opts.interactive,
456	            &step_ctx,
457	            opts.diagnostic_funnel,
458	            &ws,
459	            ui,
460	            step_display,
461	            event_bus,
462	        )?;
463	
464	        // ── Emit step completion event ──
465	        let duration_ms = exec_result.result.duration.as_millis() as u64;
466	        match exec_result.result.status() {
467	            StepStatus::Completed => {
468	                event_bus.emit(&BivvyEvent::StepCompleted {
469	                    name: self.step_name.to_string(),
470	                    success: true,
471	                    exit_code: exec_result.result.exit_code,
472	                    duration_ms,
473	                    error: None,
474	                });
475	                event_bus.emit(&BivvyEvent::StepOutcome {
476	                    name: self.step_name.to_string(),
477	                    outcome: StepOutcomeKind::Completed,
478	                    detail: None,
479	                    duration_ms: Some(duration_ms),
480	                });
481	            }
482	            StepStatus::Failed => {
483	                event_bus.emit(&BivvyEvent::StepCompleted {
484	                    name: self.step_name.to_string(),
485	                    success: false,
486	                    exit_code: exec_result.result.exit_code,
487	                    duration_ms,
488	                    error: exec_result.result.error.clone(),
489	                });
490	                event_bus.emit(&BivvyEvent::StepOutcome {
491	                    name: self.step_name.to_string(),
492	                    outcome: StepOutcomeKind::Failed,
493	                    detail: exec_result.result.error.clone(),
494	                    duration_ms: Some(duration_ms),
495	                });
496	            }
497	            StepStatus::Skipped => {
498	                let reason = exec_result
499	                    .result
500	                    .recovery_detail
501	                    .clone()
502	                    .unwrap_or_else(|| "skipped".to_string());
503	                event_bus.emit(&BivvyEvent::StepSkipped {
504	                    name: self.step_name.to_string(),
505	                    reason: reason.clone(),
506	                });
507	                // Reaching this branch means the step ran and the user chose
508	                // to skip during recovery — that's a `Declined` outcome.
509	                event_bus.emit(&BivvyEvent::StepOutcome {
510	                    name: self.step_name.to_string(),
511	                    outcome: StepOutcomeKind::Declined,
512	                    detail: Some(reason),
513	                    duration_ms: Some(duration_ms),
514	                });
515	            }
516	            _ => {}
517	        }
518	
519	        // ── Determine action ──
520	        if exec_result.aborted {
521	            return Ok(StepAction::Aborted(exec_result.result));
522	        }
523	
524	        let status = exec_result.result.status();
525	        Ok(match status {
526	            StepStatus::Completed => StepAction::Completed(exec_result.result),
527	            StepStatus::Failed => {
528	                if exec_result.skipped_by_user {
529	                    StepAction::Skipped(exec_result.result, SkipCategory::RecoverySkipped)
530	                } else {
531	                    StepAction::Failed(exec_result.result)
532	                }
533	            }
